async function seedAdminUser() {
  const { email, password, name } = config.seed;
  const existing = await prisma.user.findUnique({ where: { email } });

  if (existing) {
    console.log(`  = admin account already exists  (${email})`);
    return existing;
  }

  const user = await prisma.user.create({
    data: { email, name, passwordHash: await hashPassword(password), role: 'OWNER' },
  });
  console.log(`  + admin account created         (${email})`);
  if (password === 'ChangeMe123!') {
    console.log('    \x1b[33m⚠  Using the default password. Change it after signing in.\x1b[0m');
  }
  return user;
}

async function seedServices() {
  let created = 0;
  for (const service of SERVICES) {
    const existing = await prisma.service.findUnique({ where: { slug: service.slug }, select: { id: true } });
    if (existing) continue;
    await prisma.service.create({ data: service });
    created++;
  }
  console.log(`  ${created ? '+' : '='} services                         (${created} new, ${SERVICES.length - created} existing)`);
}

async function seedTestimonials() {
  const count = await prisma.testimonial.count();
  if (count > 0) {
    console.log(`  = testimonials                     (${count} already present)`);
    return;
  }
  await prisma.testimonial.createMany({
    data: TESTIMONIALS.map((t) => ({ ...t, rating: 5, published: true })),
  });
  console.log(`  + testimonials                     (${TESTIMONIALS.length} created)`);
}

async function seedProjects() {
  let raw;
  try {
    raw = await fs.readFile(MANIFEST, 'utf8');
  } catch {
    console.log('  ! no image manifest found — run "npm run images" first, then re-seed.');
    return;
  }

  const manifest = JSON.parse(raw);
  let created = 0;
  let updated = 0;

  for (const [index, project] of manifest.projects.entries()) {
    const existing = await prisma.project.findUnique({
      where: { slug: project.slug },
      include: { _count: { select: { images: true } } },
    });

    if (existing) {
      // Only fill in the gallery if it is empty, so an admin's own edits survive.
      if (existing._count.images === 0 && project.images.length) {
        await prisma.projectImage.createMany({
          data: project.images.map((img, i) => ({
            projectId: existing.id,
            url: img.fallback,
            alt: img.alt,
            width: img.width ?? null,
            height: img.height ?? null,
            sources: img.sources ?? [],
            sortOrder: i,
          })),
        });
      }
      updated++;
      continue;
    }

    await prisma.project.create({
      data: {
        slug: project.slug,
        title: project.title,
        category: project.category,
        location: project.location,
        year: project.year,
        summary: project.summary,
        description: project.description,
        coverImage: project.cover,
        featured: project.featured ?? false,
        published: true,
        sortOrder: index,
        images: {
          create: project.images.map((img, i) => ({
            url: img.fallback,
            alt: img.alt,
            width: img.width ?? null,
            height: img.height ?? null,
            sources: img.sources ?? [],
            sortOrder: i,
          })),
        },
      },
    });
    created++;
  }

  const totalImages = manifest.projects.reduce((sum, p) => sum + p.images.length, 0);
  console.log(
    `  ${created ? '+' : '='} projects                       (${created} new, ${updated} existing, ${totalImages} images)`,
  );
}

