async function main() {
  console.log('\n\x1b[1mSeeding Nam Interior Constructs\x1b[0m\n');

  await seedAdminUser();
  await seedServices();
  await seedTestimonials();
  await seedProjects();
  await seedSettings();

  const [users, services, projects, images, testimonials, leads] = await Promise.all([
    prisma.user.count(),
    prisma.service.count(),
    prisma.project.count(),
    prisma.projectImage.count(),
    prisma.testimonial.count(),
    prisma.lead.count(),
  ]);

  console.log('\n' + '─'.repeat(52));
  console.log(`  users ${users} · services ${services} · projects ${projects}`);
  console.log(`  images ${images} · testimonials ${testimonials} · leads ${leads}`);
  console.log('─'.repeat(52));
  console.log(`\n  Sign in at \x1b[36m${config.publicUrl}/admin/\x1b[0m`);
  console.log(`  Email:    ${config.seed.email}`);
  console.log(`  Password: ${config.seed.password}\n`);
}

main()
  .catch((error) => {
    console.error('\n✖ Seed failed:', error.message);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());
